mapper.update:
UPDATE coupon_instance
SET status = 'FROZEN', order_id = #{orderId}, frozen_at = #{now},
    freeze_expire_at = #{freezeExpireAt}, version = version + 1, updated_at = #{now}
WHERE id = #{id} AND user_id = #{userId} AND status = 'AVAILABLE'
  AND expire_at > #{now}

UPDATE coupon_instance
SET status = 'USED', used_at = #{usedAt}, version = version + 1, updated_at = #{now}
WHERE id = #{id} AND status = 'FROZEN' AND order_id = #{orderId}

UPDATE coupon_instance
SET status = CASE WHEN expire_at > #{closedAt} THEN 'AVAILABLE' ELSE 'EXPIRED' END,
    order_id = NULL, frozen_at = NULL, freeze_expire_at = NULL,
    version = version + 1, updated_at = #{now}
WHERE id = #{id} AND status = 'FROZEN' AND order_id = #{orderId}

UPDATE coupon_instance
SET status = 'AVAILABLE', order_id = NULL, used_at = NULL, expire_at = #{newExpireAt},
    version = version + 1, updated_at = #{now}
WHERE id = #{id} AND status = 'USED' AND order_id = #{orderId}
